(function(){const RECENT_UPDATES_ENDPOINT='/recent_updates.json';let recentUpdatesRequestId=0;let homepageIntroPlayed=false;function initializeHomepageIntro(){const home=document.querySelector('.notion-home');if(!home||home.dataset.introInitialized==='true'){return;}
home.dataset.introInitialized='true';if(homepageIntroPlayed){return;}
try{if(sessionStorage.getItem('kl-home-intro-played')==='true'){homepageIntroPlayed=true;return;}
sessionStorage.setItem('kl-home-intro-played','true');}catch(error){}
homepageIntroPlayed=true;home.classList.add('notion-home--intro');}
function initializeOverviewSpotlight(){const card=document.querySelector('.notion-home .notion-overview');if(!card||card.dataset.spotlightInitialized==='true'){return;}
card.dataset.spotlightInitialized='true';const spotlight=document.createElement('span');spotlight.className='notion-overview-spotlight';spotlight.setAttribute('aria-hidden','true');card.prepend(spotlight);const hoverQuery=window.matchMedia('(hover: hover) and (pointer: fine)');const motionQuery=window.matchMedia('(prefers-reduced-motion: reduce)');let frame=null;let pointerX=0;let pointerY=0;const paintSpotlight=()=>{frame=null;const bounds=card.getBoundingClientRect();const x=motionQuery.matches?bounds.width/2:pointerX-bounds.left;const y=motionQuery.matches?bounds.height/2:pointerY-bounds.top;spotlight.style.transform=`translate(${x - 180}px, ${y - 180}px)`;};const moveSpotlight=(event)=>{if(!hoverQuery.matches||event.pointerType!=='mouse'){return;}
pointerX=event.clientX;pointerY=event.clientY;if(frame===null){frame=window.requestAnimationFrame(paintSpotlight);}};card.addEventListener('pointerenter',(event)=>{if(!hoverQuery.matches||event.pointerType!=='mouse'){return;}
pointerX=event.clientX;pointerY=event.clientY;paintSpotlight();card.classList.add('notion-overview--lit');});card.addEventListener('pointermove',moveSpotlight);const clearSpotlight=()=>{card.classList.remove('notion-overview--lit');if(frame!==null){window.cancelAnimationFrame(frame);frame=null;}};card.addEventListener('pointerleave',clearSpotlight);card.addEventListener('pointercancel',clearSpotlight);}
function isHomepagePath(urlLike=window.location){const pathname=typeof urlLike==='string'?new URL(urlLike,window.location.origin).pathname:urlLike.pathname;return pathname==='/'||pathname==='/index.html';}
function hideHomepageFirstElement(){const mdTypeset=document.querySelector('.md-typeset');const firstElement=mdTypeset?.firstElementChild;if(!firstElement){return;}
firstElement.style.display='none';}
function renderEmptyState(container,text){container.innerHTML=`<p class="recent-updates-empty">${text}</p>`;}
function loadRecentUpdates(container,options={}){if(!container){return;}
const requestId=++recentUpdatesRequestId;const requestUrl=options.forceRefresh?`${RECENT_UPDATES_ENDPOINT}?t=${Date.now()}`:RECENT_UPDATES_ENDPOINT;container.innerHTML=options.forceRefresh?'<p class="recent-updates-loading">正在刷新最近更新...</p>':'<p class="recent-updates-loading">正在加载最近更新...</p>';fetch(requestUrl).then((response)=>{if(!response.ok){throw new Error(`无法加载最近更新数据: ${response.status}`);}
return response.json();}).then((data)=>{if(requestId!==recentUpdatesRequestId){return;}
if(Array.isArray(data)&&data.length>0){renderRecentUpdates(container,data);return;}
renderEmptyState(container,'暂无最近更新');}).catch((error)=>{if(requestId!==recentUpdatesRequestId){return;}
console.warn('加载最近更新失败:',error);renderEmptyState(container,'最近更新暂时无法加载');});}
function initializeHomepageRecentUpdates(){if(!isHomepagePath()){return;}
hideHomepageFirstElement();initializeHomepageIntro();initializeOverviewSpotlight();const container=document.getElementById('recent-updates-container');if(!container){return;}
loadRecentUpdates(container);}
function renderRecentUpdates(container,updates){const html=`
            <ul class="recent-updates-list">
                ${updates.map(update => `<li class="recent-update-item"><div class="recent-update-content"><a href="${update.url}"class="recent-update-title">${update.title}</a>${update.nav_path?`<div class="recent-update-nav">${update.nav_path}</div>`:''}</div><div class="recent-update-date">${update.modified_str}</div></li>`).join('')}
            </ul>
        `;container.innerHTML=html;}
window.refreshRecentUpdates=function refreshRecentUpdates(){const container=document.getElementById('recent-updates-container');if(!container){return;}
loadRecentUpdates(container,{forceRefresh:true});};if(typeof document$!=='undefined'&&typeof document$.subscribe==='function'){document$.subscribe(()=>{initializeHomepageRecentUpdates();});}else if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initializeHomepageRecentUpdates);}else{initializeHomepageRecentUpdates();}})();